第 ${n} 欄已有存檔：
${rec.label}
${fmtTime(rec.ts)}

覆蓋它嗎？

#version 300 es
precision highp float; precision highp int;
uniform highp usampler2D uH;   // 高度（世界單位，Uint16；最近鄰，判陸海用）
/* ══ 平滑高度（ver -1216）══════════════════════════════════════════════
   Ray：「山根本是方塊堆的」。成因不是 GPU —— CPU 路徑在同一個相機下長得
   一模一樣：地形的高度是**逐格最近鄰**取的，一格 20 世界單位，所以每一格
   就是一個平頂方塊，山＝一疊階梯。CPU 只是因為手機上畫質檔被推到最低、
   緩衝更小，糊掉之後看不出來而已。
   ⚠ 解法不能是「在迴圈裡抓四個角自己內插」——那是把行進迴圈裡最熱的一次
     texelFetch 變成四次。改成**多上傳一張 R16F 的高度圖、交給硬體做雙線性**：
     一次 texture() 就是內插好的值，而且是取樣器免費做的。
   ⚠ 陸海的判定仍然走最近鄰那一張（uH）：內插會把海岸的高度往海裡拉，
     判定交給它就不會有「海面被抬起來一點」這種事。 */
uniform sampler2D uHs;         // 高度（平滑；R16F + LINEAR）
uniform sampler2D uC;          // 地貌色
uniform sampler2D uS;          // 坡度 (slx,sly)，0..1 編碼（LINEAR：逐格會變成方格光影）
uniform sampler2D uMot;        // 低頻亮度起伏（BIOME 的高 4 bit，抽出來單獨一張才濾得了）
uniform sampler2D uSnow;       // 逐格雪量（ver -1220）：雪地要壓掉植被貼圖的強度
uniform sampler2D uSky;        // 這一禎的天空漸層（1 x BH）
/* 城的手繪地面（ver -1206）：最多兩座同時在畫面上 —— 城之間隔得夠遠，
   而 CITYMASK 保證同一點最多屬於一座城。
   ⚠⚠ 這一段在 GLSL 模板字串裡，**不可以用反引號**（會把字串截斷；踩第二次了）。
   ⚠ GL 的 mipmap 直接取代了 CPU 那一整套 CITY_PYR 取樣金字塔
     （§6.7.5 的「逐次減半」與逐深度挑層級全部不需要了）。 */
uniform highp usampler2D uBiome;  // 低 4 bit＝類別，高 4 bit＝低頻亮度
uniform sampler2D uMask;          // r 石橋 g 鐵路 b 道路 a 郊區
/* ⚠⚠⚠ 地貌貼圖改成 **2D array ＋ mipmap**（ver -1218，Ray：「立面陡坡才出線」）。
   實測把這一層關掉，直條紋的指標由 1.375 掉到 0.171 —— 條紋整條是它。
   原因是**縮小取樣的疊頻**：貼圖是貼在世界座標上的（一個 texel 1.6 世界單位），
   而一個螢幕像素在遠處／在**幾乎與視線平行的陡坡**上可以跨好幾十個世界單位。
   NEAREST 又沒有 mipmap ＝ 每個像素在那一片貼圖上亂點一個 texel ⇒ 直條紋與顆粒。
   ⚠ 為什麼要換成 array 而不是替原本那張「類別疊在一起」的 atlas 開 mipmap：
     那張圖是 256 寬 × (類別數×256) 高、靠程式自己 (&255) 兜出重複；
     一做 mipmap，相鄰類別的像素就會在低階層互相混進來，而且那個手兜的重複也壞了。
     array 每一層自己一片 256×256、自己 REPEAT、自己一套 mipmap，兩個問題一起沒有。 */
/* ⚠ sampler2DArray **一定要自己標精度** —— 檔頭的 precision highp float/int 不涵蓋它，
   漏了就是 'sampler2DArray' : No precision specified，整支 shader 編不過 →
   glReady:false → 悄悄退回 CPU（踩到當下唯一的徵兆是「怎麼又變慢了」）。 */
uniform highp sampler2DArray uGeo;   // 地貌貼圖（每個類別一層 256×256）
uniform sampler2D uRailDir;       // 軌道方向（降取樣）
uniform vec2 uRD;                 // RD_W, RD_H
uniform float uGeoOn;             // atlas 還沒載到就是 0
uniform sampler2D uCityA, uCityB;
uniform vec4 uCityA0, uCityB0;   // wx, wy, ca, sa
uniform vec4 uCityA1, uCityB1;   // iw, ih, kv(反分級亮度), 有效
uniform vec2 uCityT;             // 逐城的「每 1 世界單位幾個 texel」（A, B），挑 LOD 用
uniform float uInvS;             // 反分級：1/GRADE_SAT
uniform vec2 uMap, uBuf;
uniform vec3 uCam;             // x, y, alt
uniform vec2 uDir;             // sinp, cosp
uniform vec2 uLdir;            // 光的方向 lx, ly
uniform vec3 uLcol;            // lightR, G, B
uniform vec2 uLi;              // ambI, sunI
uniform vec3 uFog;             // 霧色（地平線色）
uniform float uCloudLit;
uniform float uTime;      // 毫秒，瀑布的水流動畫用
uniform float uStepK;     // 步長倍率（ver -1750，QUALITY[].step）
uniform float uZfar;      // 這一檔的視距（ver -1750，ZFAR×QUALITY[].view；深度換算仍用 ZFAR）
out vec4 o;

const float BAY[16]=float[16](${[...BAYER].map(v=>v.toFixed(5)).join(',')});
float hRaw(ivec2 t){ return float(texelFetch(uH, t, 0).r); }
/* 這一點的地表高度：陸海看最近鄰、表面高度看平滑那一張。
   ⚠ uv 用 mf/uMap —— texel 中心在 (i+0.5)，所以 mf=i+0.5 剛好取到整格的值、
     格與格之間才內插（與最近鄰版在格心完全一致，不會整體位移）。 */
/* ══⚠⚠⚠ 地形的最高點（ver -1302）══ 射線一旦高過它、而且還在往上爬，
   就**不可能再打到任何東西** —— 見主迴圈那個提早結束。由 JS 從高度圖量出來。 */
uniform float uMaxH;
/* 跳空用的 max-mipmap（ver -1303）：每一階存子格的最大值。NEAREST，走 texelFetch。 */
uniform sampler2D uHmax;
uniform int uMaxLod;
float hSurf(vec2 mf, ivec2 ti, bool outside, out bool cloud){
  if(outside){ cloud=true; return ${CLOUD_H}.0; }
  /* ⚠⚠ 陸海的界線也走**平滑高度**（ver -1219，Ray：「大陸邊緣的立面也用同樣方式處理」）。
     -1216 只把陸地的表面磨平，陸／海的分類還是逐格的布林 —— 於是大陸的輪廓
     在俯視上是一排 20 單位的方格，那就是邊緣看起來還是一堆方塊的原因。
     改成「內插後的高度掉到雲海面以下就是海」，界線變成一條**等高線**，是平滑的。
     ⚠ 舊註解怕的是「內插會把斷崖拉成緩坡」—— 實際上不會：海床遠低於雲海面，
       一格 20 單位之內高度就從幾百掉到幾十，斜率超過 10:1，讀起來仍然是垂直的崖。
     ⚠ 順帶省一次取樣：不再需要最近鄰那一張（uH）來判陸海，行進迴圈裡只剩一次 texture()。 */
  /* ⚠⚠⚠ **海也回這張圖上的值**（ver -1239）：靠岸那一圈存的是往下凹的海面
     （見 JS 端的 RIM_DEEP_*），射線因此能走到大陸的底，崖面才畫得出厚度。
     遠離陸地的海仍然是雲海面，所以外海的樣子一個字都沒變。
     ⚠ 這一段在 GLSL 的樣板字串裡，**註解不可以有反引號**（踩第七次了）。 */
  float ts = texture(uHs, mf/uMap).r;
  cloud = ts <= ${CLOUD_H}.0;
  return ts;
}
/* 城的地面：世界座標 → 這座城的 uv（與 CPU 同一條式子），回 rgb + alpha。
   ⚠ 反分級要在這裡做（CPU 是烘進金字塔的，§6.7.5）：插畫的色調是對著
     「不吃 GRADE_SAT、只除 BAKED_VAL 乘 TRIM」那條舊路校的，取樣路把城當地形畫
     會**再分級一次** —— 不反轉的話整座城會洗成灰白。 */
vec4 citySample(sampler2D tex, vec4 P0, vec4 P1, float tpw, vec2 wp, float z){
  if(P1.w<0.5) return vec4(0.0);
  vec2 r=wp-P0.xy;
  float u=(r.x*P0.z+r.y*P0.w)*P1.x+0.5;
  float v=(-r.x*P0.w+r.y*P0.z)*P1.y+0.5;
  if(u<0.0||u>=1.0||v<0.0||v>=1.0) return vec4(0.0);
  /* ⚠⚠⚠ 一定要 textureLod，**不可以用 texture()**（ver -1211，Ray 回報
     「帝都亂七八糟還有方型的底」「底色會隨著移動有直條在底部移動」）。
     texture() 的層級是硬體用**螢幕空間的導數**挑的，而這裡是 raymarch：
     相鄰的兩個像素可能打在天差地遠的深度上，導數是垃圾 → 每個 2×2 quad
     各挑一個亂七八糟的層級。挑到最粗那幾層時，整張插畫被平均成一塊（含輪廓外
     那一圈本來 alpha=0 的地方）→ alpha 不再是 0 → **整個外接矩形被畫出來**
     ＝「方型的底」；而層級逐欄跳動 ＝「隨著移動的直條」。
     正解是自己算：一個緩衝像素在這個深度覆蓋 2z/BW 個世界單位（wpp），
     層級 = log2(每世界單位的 texel 數 × wpp × CITY_LOD_K)
     —— 與 CPU 那一支挑金字塔層級的判準是同一條式子（鐵律 7）。 */
  float wpp=2.0*z/uBuf.x;
  float lod=max(log2(max(tpw*wpp*${CITY_LOD_K}, 1e-6)), 0.0);
  vec4 c=textureLod(tex, vec2(u,v), lod);
  if(c.a<=0.02) return vec4(0.0);
  float lum=dot(c.rgb, vec3(0.299,0.587,0.114));
  c.rgb=(vec3(lum)+(c.rgb-vec3(lum))*uInvS)*P1.z;
  return c;
}
ivec2 clampT(ivec2 t){ return clamp(t, ivec2(0), ivec2(uMap)-1); }

void main(){
  float px=gl_FragCoord.x, py=uBuf.y-gl_FragCoord.y;   // GL 原點在左下，畫面是左上
  float sv=(px+0.5)/uBuf.x*2.0-1.0;
  float scaleH=uBuf.y*0.62, horizon=uBuf.y*${HORIZON_F};
  float sinp=uDir.x, cosp=uDir.y;
  vec2 dir=vec2(sv*cosp - sinp, -sv*sinp - cosp);
  float curv=(1.0+sv*sv)/(2.0*${PLANET_R}.0);
  float k2=(py-horizon)/scaleH;         // (camAlt-h)/z + z*curv
  float k=k2;                           // （k 在下面的區塊裡會被 vec3 遮蔽，所以留一份 k2）
  float z=1.0, dz=0.75*uStepK;
  for(int i=0;i<900;i++){
    if(z>=uZfar) break;
    float hNeed=uCam.z-(k-z*curv)*z;
    vec2 wp=uCam.xy+dir*z;
    vec2 mf=wp*${INV_SCALE};
    ivec2 ti=ivec2(floor(mf));
    bool outside = mf.x<0.0||mf.y<0.0||mf.x>=uMap.x||mf.y>=uMap.y;
    /* ══⚠⚠⚠ 打不到就別走了（ver -1302，效能分配）════════════════════════
       hNeed ＝這一步射線所在的高度。地形的最高點是 uMaxH，所以 hNeed 大於它時
       這一步不可能命中；而 hNeed 對 z 的斜率是 -k + 2*curv*z，
       **斜率為正就代表它只會越爬越高** ⇒ 往後每一步也都打不到。
       兩者同時成立就可以直接跳出，最後輸出的天空色與 gl_FragDepth=1.0
       **與跑完 900 步一模一樣**（位元等價，不是近似）。

       ⚠⚠ **為什麼非修不可**：ZFAR 3600，而步進序列（z=1、dz=0.75、每步 +(0.0062*uStepK)）
         跑滿 **900 步只走到 z 約 3184** —— 迴圈是被**迭代上限**擋掉的，不是被 ZFAR。
         於是**每一個天空像素都把 900 步跑好跑滿**，每一步取樣一次高度貼圖。
         實測地形最高 520、巡航高度 700：**任何往上打的射線從第一步就注定
         打不到，卻照樣走 900 步。**
       ⚠⚠ 這是「把飛行地圖整個搬上 GPU」（ver -1198~-1223）漏掉的那一塊：
         CPU 那一版是**逐欄**跑的，ybuf 的地平線追蹤天然就會提早收手；
         改成**逐像素**之後每條射線各走各的，那個提早結束沒有人補回來。
       ⚠ 這不是降畫質、也不是改演算法 —— 是把「證明打不到之後還在走」的那一段砍掉。
       ⚠⚠ 這一段在 GLSL 的樣板字串裡，**註解不可以有反引號**（憲法記的第七次，
         我是第八次 —— 寫註解時順手用反引號括變數名就會炸）。 */
    if(hNeed>uMaxH && (2.0*curv*z - k)>0.0) break;
    /* ══⚠⚠⚠ 階層跳空（ver -1303）════════════════════════════════════════
       由粗到細問 max-mipmap：這一塊的最高點都在射線之下 ⇒ 整塊跳過。

       ⚠⚠ **跳的距離是「整數個原本的步」**，不是任意距離 —— 這是位元等價的關鍵。
         原序列是 z+=dz、dz+=(0.0062*uStepK)；跳 kk 步之後
           z  += dz*kk + (0.0031*uStepK)*kk*(kk-1)
           dz += (0.0062*uStepK)*kk
         射線因此**永遠落在原本會取樣的那些 z 上**，第一個命中的點一模一樣。
         跳任意距離的話取樣點會偏移，命中的 z 就變了，畫面不會等價。
       ⚠⚠ **安全距離用 DDA 算，不要用「一格的寬度」去猜**：dir 沒有正規化
         （|dir| 最大約 2.6），拿格寬當距離會一口氣跨過兩三格 ⇒ 跳過地形、畫面破洞。
         這裡算的是「沿著射線還有多遠才離開**這一塊**」，那是精確值。
       ⚠⚠ **hNeed 在區間內不是單調的**：往下看的射線它先降後升（頂點在
         z=k/(2*curv)）。所以要取區間內的**最小值**來比 —— 只看起點會漏掉
         中間那一段比較低的地方。
       ⚠ 由粗到細：命中前的空曠地帶粗階就過了（一次跳很遠），逼近地形時
         粗階擋下來、換細階，自然收斂。 */
    {
      vec2 dm = dir*${INV_SCALE};                 // 每單位 z 在地圖上走幾格
      bool jumped=false;
      for(int L=7; L>=1; L--){
        if(L>uMaxLod) continue;
        float cs = exp2(float(L));                // 這一階一格涵蓋幾個地圖格
        /* 沿射線離開這一塊還有多遠（DDA，取兩軸的較小值）。 */
        vec2 lo = floor(mf/cs)*cs;
        /* GLSL 不能用 < 比較向量（那會是編譯錯誤，而編譯錯誤就是悄悄退回 CPU）。 */
        vec2 sd = vec2(abs(dm.x)<1e-6 ? 1e-6 : dm.x, abs(dm.y)<1e-6 ? 1e-6 : dm.y);
        vec2 tv = (mix(lo, lo+cs, step(0.0, dm)) - mf) / sd;
        float adv = min(tv.x, tv.y);
        if(!(adv>0.0)) continue;
        /* 換算成「幾個原步」：(0.0031*uStepK)*kk^2 + (dz-(0.0031*uStepK))*kk = adv */
        float bq = dz - (0.0031*uStepK);
        float kk = floor((-bq + sqrt(max(bq*bq + 4.0*(0.0031*uStepK)*adv, 0.0))) / (2.0*(0.0031*uStepK)));
        if(kk < 1.0) continue;
        float zAdv = dz*kk + (0.0031*uStepK)*kk*(kk-1.0);
        float z2 = z + zAdv;
        /* 區間內 hNeed 的最小值（頂點落在區間內就取頂點）。 */
        float zv = clamp(k/(2.0*curv), z, z2);
        float hMin = min(min(uCam.z-(k-z*curv)*z, uCam.z-(k-z2*curv)*z2),
                         uCam.z-(k-zv*curv)*zv);
        float blk = texelFetch(uHmax, ivec2(mf)>>L, L).r;
        if(blk < hMin){ z=z2; dz+=(0.0062*uStepK)*kk; jumped=true; break; }
      }
      if(jumped) continue;
    }
    bool cloud; float hs=hSurf(mf, ti, outside, cloud);
    if(hs>=hNeed){
      /* 霧提前算 —— 崖面那一段要用它當閘門（同 CPU 的 fog<0.86）。 */
      float fogS=uZfar*${FOG_START};
      float fog=clamp((z-fogS)/(uZfar-fogS),0.0,1.0)*${FOG_MAX};
      vec3 c;
      /* ⚠ below 兩支都要有（雲海的天際線一樣要抗鋸齒）—— 所以提到外面宣告。 */
      float below=hs-hNeed;
      /* 上一個射線步進落在哪一格的地面：立面的落差與地貌貼圖的縱向足跡都要它。
         算一次就好（鐵律 7）—— 原本只有立面那一段在算。 */
      vec2 mfP=(uCam.xy+dir*max(z-dz,1.0))*${INV_SCALE};
      bool cP; float hPrev=hSurf(mfP, clampT(ivec2(floor(mfP))),
                                 mfP.x<0.0||mfP.y<0.0||mfP.x>=uMap.x||mfP.y>=uMap.y, cP);
      if(cloud){
        c=vec3(0.82,0.86,0.92)*uCloudLit;
      }else{
        /* 雙線性：⚠ 只在「四角都是陸地」時才內插 —— 靠海岸時鄰格是雲海高度，
           內插會把大陸邊緣拉成緩坡，斷崖就沒了（舊路徑同一條守門）。 */
        /* ⚠ 內插要錨在**格心**（ver -1217）：texel i 的中心在 mf=i+0.5，
             所以四個角要從 floor(mf-0.5) 起算。原本用 floor(mf) 等於把格值錨在
             格角上 —— 顏色會與高度差半格，而且在格心取到的是四格的混色。 */
        vec2 pc=mf-0.5; ivec2 tc=ivec2(floor(pc));
        ivec2 t00=clampT(tc), t10=clampT(tc+ivec2(1,0)),
              t01=clampT(tc+ivec2(0,1)), t11=clampT(tc+ivec2(1,1));
        float h10=hRaw(t10), h01=hRaw(t01), h11=hRaw(t11);
        vec2 f=pc-floor(pc);
        vec3 c00=texelFetch(uC,t00,0).rgb;
        if(hRaw(t00)>${CLOUD_H}.0 && h10>${CLOUD_H}.0 && h01>${CLOUD_H}.0 && h11>${CLOUD_H}.0){
          vec3 c10=texelFetch(uC,t10,0).rgb, c01=texelFetch(uC,t01,0).rgb, c11=texelFetch(uC,t11,0).rgb;
          c=mix(mix(c00,c10,f.x), mix(c01,c11,f.x), f.y);
        }else{ c=c00; }
        /* ══ 地貌貼圖層（ver -1208）══════════════════════════════════════
           與 CPU 那一支同一條邏輯：先把底色推向人造物的絕對色（石橋／鐵路／
           道路／屋頂）或水色，再乘上貼圖的「相對均值倍率」與低頻亮度起伏。
           ⚠ 乘而不換：底色帶著地貌形狀與烘焙好的 hillshade，直接換色會把山攤平。
           ⚠ 強度隨深度淡出（GEO_FAR 之後歸零）——遠景看不出紋理，省下來。 */
