        if(uGeoOn>0.5 && vegAmt>0.004){
          uint bi=texelFetch(uBiome,clampT(ti),0).r;
          uint tx=bi&15u;
          vec4 mk=texelFetch(uMask,clampT(ti),0);
          if(mk.r*255.0>40.0)        c=mix(c, vec3(138.,128.,114.)/255.0, mk.r*0.94);
          else if(tx==8u||tx==9u)    c=mix(c, (tx==9u? vec3(92.,126.,146.) : vec3(66.,100.,124.))/255.0, 0.72);
          else if(mk.g*255.0>40.0)   c=mix(c, vec3(139.,121.,101.)/255.0, mk.g*0.90);
          else if(tx==5u)            c=mix(c, vec3(135.,109.,72.)/255.0, mk.b*0.82);
