            float h10=fract(sin(dot(vec2(sB+1.0, xB    ), vec2(12.9898,78.233)))*43758.5453);
            float h01=fract(sin(dot(vec2(sB,     xB+1.0), vec2(12.9898,78.233)))*43758.5453);
            float h11=fract(sin(dot(vec2(sB+1.0, xB+1.0), vec2(12.9898,78.233)))*43758.5453);
