        float nl=clamp(0.62+dot(sl,uLdir)*${'0.030'}, 0.0, 1.5);
        float shd=(uLi.x+uLi.y*nl)*${GRADE_EXPO};
        if(!cliffDone) c=c*shd*uLcol;              // ⚠ 瀑布在上面已經自己套過光了
        float lum=dot(c, vec3(0.299,0.587,0.114));
        c=vec3(lum)+(c-vec3(lum))*${GRADE_SAT};   // VP1 分級：往亮度收斂
      }
