          if(z2>=${ZFAR}.0) break;
          float hN2=uCam.z-(kUp-z2*curv)*z2;
          vec2 mf2=(uCam.xy+dir*z2)*${INV_SCALE};
          bool o2 = mf2.x<0.0||mf2.y<0.0||mf2.x>=uMap.x||mf2.y>=uMap.y;
          bool c2; float s2=hSurf(mf2, clampT(ivec2(floor(mf2))), o2, c2);
          if(s2>=hN2){ blocked=true; break; }
          z2+=dz2; dz2+=0.011;
