      /* 抖色（ver -1209）：8bit 量化在平滑的天空與霧上會出色帶，
         逐像素套 4×4 Bayer 打散 —— 與 CPU 同一張表、同一個幅度。 */
      /* ⚠ 這張表是從 JS 的 BAYER 直接帶進來的（鐵律 7：同一份係數）。
         先前這裡是手寫的 (by*4+bx)*17%16 —— 17 ≡ 1 (mod 16)，等於
         by*4+bx，是一條線性斜坡**不是** Bayer 的分散矩陣。 */
      c+=vec3(BAY[(by<<2)|bx]*${DITHER}/255.0);
      o=vec4(c,1.0);
      gl_FragDepth=clamp(z/${ZFAR}.0,0.0,1.0);
      return;
    }
    /* ⚠ 成長率 ver -1241 由 0.011 收到 (0.0062*uStepK)（Ray：「大陸邊緣還是刺的」）：
       在 z≈1000 時一步由 4.8 個世界單位降到 3.0 —— 崖腳被步長切出的鋸齒
       （相鄰兩欄的最大落差）由 11 降到 7 個緩衝像素，實測 fps 不變（60）。
       ⚠ CPU 那一支**刻意不跟**，理由見那邊的註解。 */
    z+=dz; dz+=(0.0062*uStepK);
  }
  o=vec4(texelFetch(uSky, ivec2(0, int(py)), 0).rgb, 1.0);
  gl_FragDepth=1.0;
}

#version 300 es
in vec3 p;          // 局部座標 (lx, ly, z)
in vec2 nrm;        // 側面法線（頂面給 0,0）
in float kind;      // 0 牆側 1 屋頂側 2 牆頂 3 屋頂面 4 明指顏色
in vec3 col;        // kind==4 才用
uniform vec2 uBuf; uniform vec3 uCam; uniform vec2 uDir; uniform vec2 uLdir;
uniform vec3 uPal[8];   // 0 top 1 side 2 sideLit 3 dark 4 roofTop 5 roofSide 6 roofLit 7 roofDark
uniform vec3 uOrigin;   // 這座遺蹟的世界落點 (wx0, wy0, gh)
uniform vec2 uRot;      // ca, sa
out vec3 vCol; out float vZ;
/* 貼材（ver -1223，Ray：「上貼材」）：**GL 這一路本來完全沒有貼材** ——
   -1202 移植遺蹟時只搬了色階，tex/roofTex 那一套是 CPU 路徑的東西，
   而 GPU 現在是預設，所以畫面上一直是平塗的石頭。
   ⚠ UV 由**局部座標**算，不必多一個頂點屬性：立面沿著面的切線方向展開、
     頂面直接用 x/y。尺度與 CPU 同一條（1 個貼圖像素＝RUIN_TEXEL 個世界單位，
     所以一張 256 的圖 ＝ 256×0.7 ＝ 179.2 個世界單位，鐵律 7）。 */
out vec2 vUV; out float vRoof; out float vTexOn;
void main(){
  float wx=uOrigin.x+(p.x*uRot.x-p.y*uRot.y);
  float wy=uOrigin.y+(p.x*uRot.y+p.y*uRot.x);
  float wz=uOrigin.z+p.z;
  vec2 d=vec2(wx,wy)-uCam.xy;
  float sinp=uDir.x, cosp=uDir.y;
  float z=d.x*(-sinp)+d.y*(-cosp);
  if(z<8.0){ gl_Position=vec4(2.,2.,2.,1.); vZ=1.0; vCol=vec3(0.); return; }
  float sv=(d.x*cosp+d.y*(-sinp))/z;
  float scaleH=uBuf.y*0.62, horizon=uBuf.y*${HORIZON_F};
  float curv=(1.0+sv*sv)/(2.0*${PLANET_R}.0);
  float sy=((uCam.z-wz)/z + z*curv)*scaleH+horizon;
  gl_Position=vec4(sv, 1.0-2.0*sy/uBuf.y, 0.0, 1.0);
  vZ=clamp(z/${ZFAR}.0,0.0,1.0);
  vec3 c;
  if(kind>3.5)      c=col;
  else if(kind>2.5) c=uPal[4];
  else if(kind>1.5) c=uPal[0];
  else{
    float dl=dot(nrm,uLdir);
    bool rf=kind>0.5;
    if(dl>0.30)       c=rf?uPal[6]:uPal[2];
    else if(dl<-0.30) c=rf?uPal[7]:uPal[3];
    else              c=rf?uPal[5]:uPal[1];
  }
  vCol=c;
  /* kind：0 牆側 1 屋頂側 2 牆頂 3 屋頂面 4 明指顏色（開口／地板 → 不貼材）。 */
  float TS=${(256*0.7).toFixed(1)};
  if(kind>1.5) vUV=vec2(p.x,p.y)/TS;                       // 頂面
  else         vUV=vec2(p.x*(-nrm.y)+p.y*nrm.x, p.z)/TS;   // 立面：沿切線展開
  vRoof  = (kind>0.5 && kind<1.5) || (kind>2.5 && kind<3.5) ? 1.0 : 0.0;
  vTexOn = kind>3.5 ? 0.0 : 1.0;
}

#version 300 es
precision highp float;
in vec3 vCol; in float vZ;
in vec2 vUV; in float vRoof; in float vTexOn;
uniform vec3 uAmb; uniform float uAmbA; uniform float uAlpha;
uniform sampler2D uTexW, uTexR;
uniform float uTexOn;          // 那一座有沒有貼材（0＝沒有，照舊平塗）
out vec4 o;
void main(){
  /* 貼材：與 CPU 同一個配方 —— 面先塗色階，再把貼圖以 **0.42** 疊上去
     （CPU 那一支是 globalAlpha=0.42 的 multiply，鐵律 7 的同一個數字）。
     ⚠ 這裡是一般的三角形光柵化，導數是有效的 —— 所以**可以**用 texture()
       讓硬體挑 mipmap（與地形那邊 raymarch 不可以用隱含層級是兩回事）。 */
  /* ⚠⚠ **不要自己套霧**：CPU 那一支也沒有。§6.8.1 的環境光取樣取的是
     「畫面上旁邊那塊地形的顏色」，而那個顏色**已經把光照、分級、霧、時段
     全部算進去了** —— 再套一次霧就是把同一件事算兩遍（鐵律 7），
     遠處的遺蹟會比地形更灰。這裡照 CPU 的作法只做一次環境光疊色
     （source-atop 等價於 mix）。 */
  vec3 c=vCol;
  if(uTexOn>0.5 && vTexOn>0.5){
    vec3 t = (vRoof>0.5 ? texture(uTexR, vUV) : texture(uTexW, vUV)).rgb;
    /* ⚠⚠⚠ **乘不是蓋**（ver -1228，Ray：「貼材顏色太白太亮」）。
       原本是 mix(c, t, 0.42)（＝CPU 的 source-over）—— 那是把面的顏色往**貼圖自己的
       亮度**拉：moss_stone 的平均是 (179,183,176)，比色階的暗面 (148,154,146) 亮，
       於是暗面被提亮、亮面被壓平，**整座洗白、而且立體感不見了**。
       改成乘：c *= (1-a) + a*t —— 貼圖只**調製**明暗，不改變面與面之間的關係。
       ⚠ 這正是地貌貼圖層早就在用的作法（「乘而不換：底色帶著烘焙好的 hillshade，
         直接換色會把山攤平」）—— 同一個問題的同一個答案。
       ⚠ a 仍然是 **0.42**（與 CPU 同一個數字，鐵律 7）。副作用是整體暗一階
         （貼圖平均 ≈0.70 ⇒ ×0.87），那正是 Ray 要的方向。 */
    c *= (1.0-0.42) + 0.42*t;
  }
  o=vec4(mix(c,uAmb,uAmbA), uAlpha);
  gl_FragDepth=vZ;
}

#version 300 es
in vec3 p;        // 局部座標（u*hw, v*hh, 高度）
in vec2 nrm;      // 牆的法線（屋頂給 0,0）
in float kind;    // 0 牆 1 屋頂
in vec2 uv;       // 屋頂在 atlas 上的座標
uniform vec2 uBuf; uniform vec3 uCam; uniform vec2 uDir;
uniform vec3 uOrigin; uniform vec2 uRot;
out float vKind; out vec2 vUv; out float vZ; out float vShade;
void main(){
  float wx=uOrigin.x+(p.x*uRot.x-p.y*uRot.y);
  float wy=uOrigin.y+(p.x*uRot.y+p.y*uRot.x);
  float wz=uOrigin.z+p.z;
  vec2 d=vec2(wx,wy)-uCam.xy;
  float sinp=uDir.x, cosp=uDir.y;
  float z=d.x*(-sinp)+d.y*(-cosp);
  if(z<8.0){ gl_Position=vec4(2.,2.,2.,1.); vZ=1.0; vKind=0.0; vUv=vec2(0.); vShade=1.0; return; }
  float sv=(d.x*cosp+d.y*(-sinp))/z;
  float scaleH=uBuf.y*0.62, horizon=uBuf.y*${HORIZON_F};
  float curv=(1.0+sv*sv)/(2.0*${PLANET_R}.0);
  float sy=((uCam.z-wz)/z + z*curv)*scaleH+horizon;
  gl_Position=vec4(sv, 1.0-2.0*sy/uBuf.y, 0.0, 1.0);
  vZ=clamp(z/${ZFAR}.0,0.0,1.0);
  vKind=kind; vUv=uv; vShade=1.0;
}

#version 300 es
precision highp float;
in float vKind; in vec2 vUv; in float vZ; in float vShade;
uniform sampler2D uAtlas;
uniform vec4 uWall;     // 牆色（含 alpha，與 CPU 的 wallCol 同值）
uniform float uAlpha;   // 這一禎整層的濃度（淡入淡出，與 CPU 同一個 _massA）
uniform vec3 uFog; uniform float uFogK;
out vec4 o;
void main(){
  vec4 c;
  if(vKind>0.5){ c=texture(uAtlas,vUv); if(c.a<0.02) discard; }
  else          c=uWall;
  /* 霧：與地形同一條曲線（量體是貼在地上的東西，要跟著沉進大氣）。 */
  float fogS=${ZFAR}.0*${FOG_START};
  float fog=clamp((vZ*${ZFAR}.0-fogS)/(${ZFAR}.0-fogS),0.0,1.0)*${FOG_MAX}*uFogK;
  o=vec4(mix(c.rgb,uFog,fog), c.a*uAlpha);
  gl_FragDepth=vZ;
}
